CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_status AS ENUM ('ACTIVE','INACTIVE','LOCKED');
CREATE TYPE assignment_status AS ENUM ('ACTIVE','ENDED','REVOKED');
CREATE TYPE question_type AS ENUM ('MCQ','TRUE_FALSE','SHORT_ANSWER');
CREATE TYPE question_status AS ENUM ('DRAFT','ACTIVE','ARCHIVED');
CREATE TYPE quiz_status AS ENUM ('DRAFT','SCHEDULED','PUBLISHED','ACTIVE','CLOSED','ARCHIVED');
CREATE TYPE attempt_status AS ENUM ('IN_PROGRESS','SUBMITTED','EXPIRED','EVALUATED');
CREATE TYPE notification_status AS ENUM ('UNREAD','READ','ARCHIVED');

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, first_name text NOT NULL, last_name text NOT NULL, phone text, status user_status NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_login_at timestamptz);
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE CHECK (name IN ('ADMIN','MENTOR','STUDENT')));
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE RESTRICT, PRIMARY KEY (user_id, role_id));
CREATE TABLE departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, code text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE programs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), department_id uuid NOT NULL REFERENCES departments(id), name text NOT NULL, code text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE academic_years (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL UNIQUE, starts_on date NOT NULL, ends_on date NOT NULL, CHECK (ends_on > starts_on));
CREATE TABLE semesters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), academic_year_id uuid NOT NULL REFERENCES academic_years(id), name text NOT NULL, sequence_no int NOT NULL CHECK (sequence_no > 0), UNIQUE (academic_year_id, sequence_no));
CREATE TABLE students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES users(id), student_register_number text NOT NULL UNIQUE, department_id uuid NOT NULL REFERENCES departments(id), program_id uuid NOT NULL REFERENCES programs(id), academic_year_id uuid NOT NULL REFERENCES academic_years(id), semester_id uuid NOT NULL REFERENCES semesters(id), date_of_birth date, admission_year int NOT NULL CHECK (admission_year BETWEEN 1900 AND 2200), status user_status NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE faculty (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES users(id), employee_id text NOT NULL UNIQUE, department_id uuid NOT NULL REFERENCES departments(id), designation text NOT NULL, status user_status NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mentor_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mentor_id uuid NOT NULL REFERENCES faculty(id), student_id uuid NOT NULL REFERENCES students(id), assigned_by uuid NOT NULL REFERENCES users(id), assigned_at timestamptz NOT NULL DEFAULT now(), effective_from timestamptz NOT NULL, effective_until timestamptz, status assignment_status NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (effective_until IS NULL OR effective_until > effective_from));
CREATE UNIQUE INDEX one_active_assignment_per_student ON mentor_assignments(student_id) WHERE status = 'ACTIVE';
CREATE INDEX mentor_assignments_mentor_idx ON mentor_assignments(mentor_id, status);
CREATE TABLE subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), department_id uuid NOT NULL REFERENCES departments(id), name text NOT NULL, code text NOT NULL UNIQUE);
CREATE TABLE topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_id uuid NOT NULL REFERENCES subjects(id), name text NOT NULL, UNIQUE(subject_id, name));
CREATE TABLE questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL REFERENCES users(id), subject_id uuid NOT NULL REFERENCES subjects(id), topic_id uuid REFERENCES topics(id), question_text text NOT NULL, question_type question_type NOT NULL, difficulty text NOT NULL CHECK (difficulty IN ('EASY','MEDIUM','HARD')), marks numeric(8,2) NOT NULL CHECK (marks > 0), explanation text, status question_status NOT NULL DEFAULT 'DRAFT', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE question_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE, option_text text NOT NULL, is_correct boolean NOT NULL DEFAULT false, display_order int NOT NULL CHECK (display_order > 0), UNIQUE(question_id, display_order));
CREATE TABLE quizzes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL REFERENCES users(id), title text NOT NULL, join_code text UNIQUE, description text, instructions text, subject_id uuid NOT NULL REFERENCES subjects(id), duration_minutes int NOT NULL CHECK (duration_minutes > 0), total_marks numeric(8,2) NOT NULL CHECK (total_marks > 0), passing_marks numeric(8,2) NOT NULL CHECK (passing_marks >= 0 AND passing_marks <= total_marks), start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, attempt_limit int NOT NULL DEFAULT 1 CHECK (attempt_limit > 0), status quiz_status NOT NULL DEFAULT 'DRAFT', randomize_questions boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, CHECK (end_at > start_at));
CREATE TABLE quiz_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quiz_id uuid NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES questions(id), question_text_snapshot text NOT NULL, question_type_snapshot question_type NOT NULL, marks numeric(8,2) NOT NULL CHECK (marks > 0), display_order int NOT NULL CHECK (display_order > 0), UNIQUE(quiz_id, question_id), UNIQUE(quiz_id, display_order));
CREATE TABLE quiz_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quiz_id uuid NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id), assigned_by uuid NOT NULL REFERENCES users(id), assigned_at timestamptz NOT NULL DEFAULT now(), status assignment_status NOT NULL DEFAULT 'ACTIVE', UNIQUE(quiz_id, student_id));
CREATE TABLE quiz_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quiz_id uuid NOT NULL REFERENCES quizzes(id), student_id uuid NOT NULL REFERENCES students(id), attempt_number int NOT NULL CHECK (attempt_number > 0), started_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, submitted_at timestamptz, status attempt_status NOT NULL DEFAULT 'IN_PROGRESS', UNIQUE(quiz_id, student_id, attempt_number));
CREATE TABLE quiz_answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES quiz_attempts(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES quiz_questions(id), selected_option_id uuid REFERENCES question_options(id), text_answer text, marks_awarded numeric(8,2), is_correct boolean, feedback text, answered_at timestamptz NOT NULL DEFAULT now(), UNIQUE(attempt_id, question_id));
CREATE TABLE quiz_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL UNIQUE REFERENCES quiz_attempts(id), student_id uuid NOT NULL REFERENCES students(id), quiz_id uuid NOT NULL REFERENCES quizzes(id), total_marks numeric(8,2) NOT NULL, obtained_marks numeric(8,2) NOT NULL CHECK (obtained_marks >= 0), percentage numeric(5,2) NOT NULL CHECK (percentage >= 0 AND percentage <= 100), pass_status boolean, evaluated_at timestamptz, evaluated_by uuid REFERENCES users(id));
CREATE TABLE feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mentor_id uuid NOT NULL REFERENCES faculty(id), student_id uuid NOT NULL REFERENCES students(id), quiz_id uuid REFERENCES quizzes(id), meeting_id uuid, feedback_type text NOT NULL CHECK (feedback_type IN ('GENERAL','QUIZ','ACADEMIC','PERFORMANCE','IMPROVEMENT')), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mentor_meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mentor_id uuid NOT NULL REFERENCES faculty(id), student_id uuid NOT NULL REFERENCES students(id), title text NOT NULL, description text, scheduled_start timestamptz NOT NULL, scheduled_end timestamptz NOT NULL, location text, meeting_type text NOT NULL, status text NOT NULL CHECK (status IN ('SCHEDULED','COMPLETED','CANCELLED')), notes text, action_items text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (scheduled_end > scheduled_start));
ALTER TABLE feedback ADD CONSTRAINT feedback_meeting_fk FOREIGN KEY (meeting_id) REFERENCES mentor_meetings(id);
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type text NOT NULL, title text NOT NULL, message text NOT NULL, reference_type text, reference_id uuid, status notification_status NOT NULL DEFAULT 'UNREAD', created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
CREATE TABLE announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL REFERENCES users(id), title text NOT NULL, content text NOT NULL, audience text NOT NULL CHECK (audience IN ('ALL','STUDENTS','MENTORS','SPECIFIC_DEPARTMENT','SPECIFIC_PROGRAM')), department_id uuid REFERENCES departments(id), program_id uuid REFERENCES programs(id), priority text NOT NULL DEFAULT 'NORMAL', publish_at timestamptz NOT NULL, expires_at timestamptz, status text NOT NULL DEFAULT 'DRAFT', CHECK (expires_at IS NULL OR expires_at > publish_at));
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, ip_address inet, user_agent text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX students_department_idx ON students(department_id, status);
CREATE INDEX quizzes_status_window_idx ON quizzes(status, start_at, end_at);
CREATE INDEX quiz_assignments_student_idx ON quiz_assignments(student_id, status);
CREATE INDEX attempts_student_idx ON quiz_attempts(student_id, status);
CREATE INDEX notifications_user_idx ON notifications(user_id, status, created_at DESC);
CREATE INDEX audit_logs_entity_idx ON audit_logs(entity_type, entity_id, created_at DESC);
